/// One font's metrics, in thousandths of the font size.
pub(super) struct Metrics {
    /// Glyph names in sorted order.
    pub names: &'static [&'static str],
    /// The width of the glyph of the same position in `names`.
    pub widths: &'static [u16],
    /// The font's bounding box: left, bottom, right, top.
    pub bounding_box: [i16; 4],
    pub ascender: i16,
    pub descender: i16,
    pub cap_height: i16,
    pub x_height: i16,
    /// Degrees counterclockwise from vertical.
    pub italic_angle: f32,
}

